import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"RGW for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"RGW for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","RGW","对象存储","性能优化","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/RGW_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/RGW_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/RGW_for_Ceph_Developer_Summit_-_Vampire.md"};function d(l,t,s,n,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<p>本文为 Ceph Developer Summit Vampire 版本 RGW 专题会议纪要，涵盖有序 bucket 索引、BI log FIFO 卸载、S3 Vectors 新接口以及 RGW admission control 等核心议题。</p><h2 id="一、有序-bucket-索引-ordered-bucket-index" tabindex="-1">一、有序 Bucket 索引（Ordered Bucket Index） <a class="header-anchor" href="#一、有序-bucket-索引-ordered-bucket-index" aria-label="Permalink to &quot;一、有序 Bucket 索引（Ordered Bucket Index）&quot;">​</a></h2><h3 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h3><p>RGW 自诞生起就采用基于 hash 的 bucket 索引分片机制：对对象名计算 hash 值，再对分片数取模，确定该对象落在哪个 shard。这一方式查询速度快、时间复杂度为 O(1)，绝大多数场景下表现良好。</p><p>然而，在需要对 bucket 进行有序列举（ordered listing）时，该方案存在明显瓶颈：对象名在各 shard 之间并非按字典序（lexicographic）排列，因此列举时需要向所有 shard 发起查询，通过类似 selection sort 的方式合并结果，IO 开销极大。在对象数量达到十亿级别、分片数达到千万级时，问题尤为突出。</p><p>此外，传统 reshard 过程需要暂停写入（stop writes），待 reshard 完成后才能恢复，影响可用性。</p><h3 id="有序索引方案" tabindex="-1">有序索引方案 <a class="header-anchor" href="#有序索引方案" aria-label="Permalink to &quot;有序索引方案&quot;">​</a></h3><p>Eric 提出的有序 bucket 索引方案将对象名按字典序存储在各 shard 中：第一个 shard 存储字典序最小的对象，最后一个 shard 存储字典序最大的对象。这样 bucket listing 只需按 shard 顺序逐个读取，效率大幅提升。</p><p>另一个关键优势是 reshard 变为本地操作：当某个 shard 超过 100,000 条记录时，只需将该 shard 一分为二（split），各保留约 50,000 条，无需停止其他 shard 的写入。</p><p>分片边界（split points）存储在 bucket instance 对象的 OMAP 中，写入对象时需先读取这些 split points 以确定对应 shard，相比 hash 方案多了一次额外读取。</p><h3 id="当前进展与讨论" tabindex="-1">当前进展与讨论 <a class="header-anchor" href="#当前进展与讨论" aria-label="Permalink to &quot;当前进展与讨论&quot;">​</a></h3><ul><li>当前 PR 主要供测试使用，支持 hash → ordered 以及 ordered → hash 的相互转换</li><li>动态 reshard（split/merge）尚未实现，是下一个主要里程碑</li><li>hash → ordered 转换期间仍需锁定 bucket，且由于无法利用日志化二阶段 reshard，锁定时间可能略长于现有方案</li></ul><p><strong>配置方式讨论</strong>：与会者讨论了将 bucket 索引方案设为 zone 级别配置项的可能性，而非仅作 RGW 级别的 config 选项，因为同一集群的多个 RGW 不应使用不同的索引方案。也有人提出可参考 unindexed bucket 的实现，通过 bucket 创建时的属性或扩展 S3 make bucket 命令来指定索引类型。</p><p><strong>OMAP 缓存问题</strong>：有序方案引入了对 split points 的额外读取，与会者讨论了利用缓存来降低开销的可能性。但也指出在大规模场景（如 10,000 个 shard 时有 10,000 个 split points）缓存效率会下降。此外，Gabby 此前曾发现 bucket listing 会大量污染 RocksDB block cache，导致写入 IO 受影响。RocksDB 存在一个不缓存特定读取操作的 API，但目前未暴露给 RADOS 接口，建议与 core 团队协作推进该能力的开放。</p><h2 id="二、bi-log-fifo-卸载-bi-log-offload-to-fifo" tabindex="-1">二、BI Log FIFO 卸载（BI Log Offload to FIFO） <a class="header-anchor" href="#二、bi-log-fifo-卸载-bi-log-offload-to-fifo" aria-label="Permalink to &quot;二、BI Log FIFO 卸载（BI Log Offload to FIFO）&quot;">​</a></h2><p>Schulpa 介绍了将 bucket index log（BI log）从 bucket index 对象（OMAP）迁移到 FIFO 队列的工作。</p><h3 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to &quot;动机&quot;">​</a></h3><p>当前 BI log 与 bucket index 使用同一组 RADOS 对象，二者的写入会形成竞争（contention），在 bucket 规模扩大时影响可扩展性。将 BI log 解耦到独立的 FIFO 对象，可降低竞争并提升性能。</p><h3 id="实现要点" tabindex="-1">实现要点 <a class="header-anchor" href="#实现要点" aria-label="Permalink to &quot;实现要点&quot;">​</a></h3><ul><li>引入 backend 抽象层，支持通过 <code>bucket_info.layout.logs</code> 字段选择存储后端：<code>index</code>（保持原有行为）或 <code>fifo</code>（写入独立的 FIFO 对象）</li><li>每个 bucket 使用独立的 FIFO 对象，分片数采用对数扩展（logarithmic scaling）：即使 bucket 有 1999 个 index shard，BI log 最多只需 21 个 FIFO shard（范围 7~21）</li><li>FIFO shard 数量少于 index shard 数量，且 BI log 会被定期 trim，无需与 index 使用相同的分片粒度</li><li>接口设计与 data log 保持一致（lazy FIFO、push/list/trim），便于复用</li><li>迁移机制基于 generation 机制，在 reshard 时触发切换，也支持回退到 OMAP 方式</li></ul><h3 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h3><ul><li>功能实现已基本完成，正在进行小规模测试</li><li>尚未完成大规模压力测试，需与 Eric 的有序索引工作协同 rebase 后进行</li><li>当前每个对象操作会对应一个独立的 FIFO 写入，批量合并写入（batching）作为后续优化项</li></ul><h2 id="三、s3-vectors-新接口" tabindex="-1">三、S3 Vectors 新接口 <a class="header-anchor" href="#三、s3-vectors-新接口" aria-label="Permalink to &quot;三、S3 Vectors 新接口&quot;">​</a></h2><p>Yuval 介绍了正在开发的 S3 Vectors 接口，该接口为 RGW 增加向量数据库能力。</p><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>该接口基于 AWS 约一年前发布的 S3 Vectors 规范，核心思路是将向量数据库与对象存储深度融合：不是让向量数据库以 S3 为后端存储，而是直接在 S3 语义下实现向量数据库能力。</p><h3 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h3><p>底层向量数据库采用 <strong>LanceDB</strong>，选择原因：</p><ol><li>近一两年持续活跃、贡献度高，是新兴技术中较为稳定的选择</li><li>完全嵌入式（embedded），无独立 daemon，客户端代码即数据库全部逻辑，避免引入额外依赖和管理复杂度</li></ol><p>LanceDB 使用 Rust 编写，为此开发了 FFI 层（C API），使 Ceph C++ 代码能调用其接口。同时新增 <strong>libsal</strong>（SAL 的 C API），供 Rust 代码在进程内直接调用存储层，无需通过 S3 协议绕一圈。</p><h3 id="开发状态与待完成工作" tabindex="-1">开发状态与待完成工作 <a class="header-anchor" href="#开发状态与待完成工作" aria-label="Permalink to &quot;开发状态与待完成工作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>状态</th></tr></thead><tbody><tr><td>核心向量操作</td><td>开发中（feature branch）</td></tr><tr><td>文档 PR</td><td>已开放，欢迎 review</td></tr><tr><td>后台处理线程（re-indexing、compaction）</td><td>进行中，不阻塞首个可用版本</td></tr><tr><td>async IO（Tokio ↔ Seastar 协程互通）</td><td>进行中，当前所有调用为同步阻塞</td></tr><tr><td>分布式索引缓存层（向量查询亲和性缓存）</td><td>待研究，可能在 Vampire 时间窗内完成</td></tr></tbody></table><p>Yuval 特别希望社区成员先阅读文档 PR，文档撰写过程中已暴露并修复多个 bug，欢迎就接口设计、语义完整性等提供反馈。</p><h2 id="四、rgw-admission-control-过载保护" tabindex="-1">四、RGW Admission Control / 过载保护 <a class="header-anchor" href="#四、rgw-admission-control-过载保护" aria-label="Permalink to &quot;四、RGW Admission Control / 过载保护&quot;">​</a></h2><p>Marcel 围绕 RGW 过载保护（admission control）问题展开讨论，并分享了相关工程背景和方案探索。</p><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>某生产环境出现部分 PG 降级，导致 RGW 大量请求挂起，线程数飙升至约 500，触发 Kubernetes liveness probe 失败进入 crash loop，最终造成大范围服务中断。根因是少量 PG 异常却引发了全局线程耗尽（thread exhaustion）。</p><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><ul><li><code>rgw_max_concurrent_requests</code> 静态阈值难以适配不同负载和系统规模</li><li>超过阈值后确实会返回 503，但合理阈值难以事先确定</li><li>阈值既与内存消耗相关（每个大对象请求占用最多 16MB），也与后端 RADOS 响应速度相关</li></ul><h3 id="方案探索" tabindex="-1">方案探索 <a class="header-anchor" href="#方案探索" aria-label="Permalink to &quot;方案探索&quot;">​</a></h3><ol><li><p><strong>自适应并发限制器（Gradient2 算法）</strong>：参考 Envoy 和 Netflix 的实现，持续测量系统延迟，动态调整 inflight 请求上限，使系统保持在&quot;膝点&quot;（knee of the curve）以内，超出部分直接返回 503。已有 draft PR，在小规模系统上验证有效。</p></li><li><p><strong>分布式限流器（Distributed Rate Limiter）</strong>：正在设计中（有 design PR），用于解决多租户公平性问题，防止单个用户占用全部带宽。</p></li><li><p><strong>RADOS 背压（Pushback）机制</strong>：当前 RADOS/OSD 不支持主动拒绝请求，请求一旦发出只能等待响应，即使 OSD 极度繁忙。讨论认为 RGW 场景下或许可以支持某种形式的 OSD 背压信号，但实现复杂度较高。</p></li><li><p><strong>内存目标驱动配置</strong>：Casey 提出可由用户为 RGW 配置一个内存预算，由 RGW 自动推算合适的并发请求数、线程数等参数，降低调优门槛。</p></li><li><p><strong>OSD 优先级缓存系统复用</strong>：有人建议参考 OSD 侧现有的 priority cache 机制，在 RGW 侧实现类似的资源优先级管理。</p></li></ol><p><strong>讨论结论</strong>：与会者一致认为需区分两类问题——①用户公平性（防止某用户独占带宽）应由分布式限流器解决；②后端异常导致的系统过载（OSD/PG 慢）更适合通过背压或自适应并发控制来缓解。建议 Marcel 在 RGW weekly refactor 会议上进一步介绍相关工作，Matt Benjamin 预计会参与讨论。</p><p><strong>延迟监控工具</strong>：Marcel 还提交了基于 Prometheus 兼容格式的 per-operation 延迟直方图 perf counter PR，作为 admission control 的基础度量工具。Adam 建议将 core perf counter 修改与 RGW 变更合并为一个 PR，并确保同时覆盖 core 测试和 RGW 测试。</p><h2 id="五、后续行动项" tabindex="-1">五、后续行动项 <a class="header-anchor" href="#五、后续行动项" aria-label="Permalink to &quot;五、后续行动项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>事项</th></tr></thead><tbody><tr><td>Eric</td><td>推进有序 bucket 索引的 split/merge 实现；与测试团队协作完成大规模测试</td></tr><tr><td>Eric / Schulpa</td><td>协同 rebase，确保 BI log FIFO 与有序索引可兼容运行</td></tr><tr><td>Schulpa</td><td>完成 BI log FIFO 大规模压力测试；研究批量写入优化</td></tr><tr><td>Yuval</td><td>推进文档 PR review；完成后台处理线程及 async IO 方案</td></tr><tr><td>Marcel</td><td>在 RGW weekly refactor 会议分享 admission control 工作</td></tr><tr><td>Adam</td><td>邀请 Matt Benjamin 参加 Marcel 的 admission control 讨论</td></tr><tr><td>RGW + Core 团队</td><td>探讨 RocksDB OMAP 缓存控制 API 暴露给 RADOS 接口的可行性</td></tr><tr><td>待定</td><td>调研 zone 级别 bucket 索引类型配置方案</td></tr></tbody></table>',45)])])}const b=e(i,[["render",d]]);export{u as __pageData,b as default};
